class Solution:
    def createTargetArray(self, nums: List[int], index: List[int]) -> List[int]:
        target = [0] * len(nums)
        size = 0
        for i in range(len(nums)):
            for j in range(size, index[i], -1):
                target[j] = target[j - 1]
            target[index[i]] = nums[i]
            size += 1
        return target

